examples.sql:
SELECT tp_sparkline([1, 3, 2, 5, 4, 6],
  theme := 'ascii_basic');

SELECT tp_density([1, 5, 3, 8, 2],
  style := 'ascii');

SELECT tp_sparkline(
  array_agg(value ORDER BY step),
  theme := 'ascii_basic'
) AS trend
FROM (VALUES (1, 4.0), (2, 7.0),
             (3, 5.0)) AS t(step, value);
